 * Token bucket and sliding window rate limiters. Each keeps one independent
 * state per key, created the first time that key reaches the policy.
 */

export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  #state(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { units: this.capacity * this.per, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key, tick)
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const cap = this.capacity * this.per
      state.units += this.refill * delta
      if (state.units > cap) state.units = cap
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).units >= this.per
  }

  record(key) {
    this.states.get(key).units -= this.per
  }
}

export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.ticks.length && state.ticks[cut] <= threshold) cut++
    if (cut > 0) state.ticks.splice(0, cut)
  }

  allows(key) {
    const state = this.states.get(key)
    return BigInt(state.ticks.length) < this.limit
  }

  record(key) {
    this.states.get(key).ticks.push(this.states.get(key).lastTick)
  }
}
"}

