{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-be2WvB/src/parse.js","content":"/**
 * Parses a limiter file into policy declarations, route declarations and
 * events, validating every line against the written grammar as it goes.
 */
import { ParseError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function checkName(word, line, kind, message) {
  if (!NAME_RE.test(word)) throw new ParseError(line, `${message} ${word}`)
}

function checkInt(word, line, field, min) {
  if (!INT_RE.test(word) || BigInt(word) < BigInt(min)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return BigInt(word)
}

export function parseProgram(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const line = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    if (!['bucket', 'window', 'route', 'event'].includes(directive)) {
      throw new ParseError(line, `unknown directive ${directive}`)
    }
    if (directive !== 'event' && seenEvent) {
      throw new ParseError(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = tokens
      checkName(name, line, 'name', 'invalid policy name')
      const capacity = checkInt(capacityStr, line, 'capacity', 1)
      const refill = checkInt(refillStr, line, 'refill', 0)
      const per = checkInt(perStr, line, 'per', 1)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (tokens.length !== 4) throw new ParseError(line, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
      checkName(name, line, 'name', 'invalid policy name')
      const limit = checkInt(limitStr, line, 'limit', 0)
      const span = checkInt(spanStr, line, 'span', 1)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, { type: 'window', limit, span })
    } else if (directive === 'route') {
      if (tokens.length < 3) throw new ParseError(line, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      checkName(prefix, line, 'prefix', 'invalid route prefix')
      for (const name of policyNames) {
        checkName(name, line, 'name', 'invalid policy name')
        if (!policies.has(name)) throw new ParseError(line, `unknown policy ${name}`)
      }
      if (routes.some((r) => r.prefix === prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
      routes.push({ prefix, policyNames })
    } else {
      if (tokens.length !== 3) throw new ParseError(line, 'expected event <tick> <key>')
      const [, tickStr, key] = tokens
      const tick = checkInt(tickStr, line, 'tick', 0)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(line, `tick ${tick} is before tick ${lastTick}`)
      }
      checkName(key, line, 'key', 'invalid key')
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    }
  }

  return { policies, routes, events }
}
"}

