  let totalDenied = 0n
  for (const v of verdicts) {
    let counts = perKey.get(v.key)
    if (!counts) {
      counts = { allowed: 0n, denied: 0n }
      perKey.set(v.key, counts)
    }
    if (v.allow) {
      counts.allowed += 1n
      totalAllowed += 1n
    } else {
      counts.denied += 1n
      totalDenied += 1n
    }
  }
  const keys = [...perKey.keys()].sort()
  const lines = keys.map((key) => {
    const c = perKey.get(key)
    return `${key} allowed=${c.allowed} denied=${c.denied}`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    fail('usage: cli.js replay|summary', 2)
    return
  }
  const mode = args[0]

  const text = await readStdin()
  let program
  try {
    program = parseProgram(text)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message, 2)
      return
    }
    throw err
  }

  const verdicts = simulate(program)
  const output = mode === 'replay' ? formatReplay(verdicts) : formatSummary(verdicts)
  process.stdout.write(output)
}

main().catch((err) => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
